contracts.definition:
async runHandoff(srcSessionId: string, reply?: string): Promise<void>
// agent-driven：源 session 跑 handoff turn → 等 agent_end 提取 doc → create 新 session → newClient.prompt(doc) 注入 → 广播 handoffComplete
// 抛错：HANDOFF_ALREADY_IN_PROGRESS / HANDOFF_NO_HISTORY（getHistory 空）/ HANDOFF_TIMEOUT（600s）/ HANDOFF_EMPTY_DOC / create/prompt 失败原 error

async abortHandoff(srcSessionId: string): Promise<void>
// 中断进行中的 handoff：client.abort() + clearTimeout + detachListener + reject(ABORTED) + Map.delete
// 幂等：inflight 无此 session 时静默 no-op
// abort 失败（pi 卡死）catch 不 rethrow（ES4）

function extractFinalTextFromAgentEnd(messages: PiAgentEndMessage[] | undefined): string
// 从 messages 末条 content（unknown）提取 type==='text' block join 成字符串
// 空/undefined/无 text → ''（调用方判空报错 HANDOFF_EMPTY_DOC）

interface InflightHandoff {
  detachListener: () => void
  timeoutTimer: ReturnType<typeof setTimeout>
  resolve: (doc: string) => void
  reject: (err: Error) => void
  srcClient: IPiEngine
}
// handoff-service private，不导出
